from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
eps=df['eps'].values; T=df['T'].values; s=df['sigma'].values
Ft={
 'eps^p': (lambda p,e: e**p[0], 1),
 'cos(d eps)': (lambda p,e: np.cos(p[0]*e), 1),
 'sin(d eps)': (lambda p,e: np.sin(p[0]*e), 1),
 'exp(-d eps)': (lambda p,e: np.exp(-p[0]*e), 1),
 'eps exp(-d eps)': (lambda p,e: e*np.exp(-p[0]*e), 1),
 'eps^p exp(-d eps)': (lambda p,e: e**p[0]*np.exp(-p[1]*e), 2),
 '1/(1+d eps)': (lambda p,e: 1/(1+p[0]*e), 1),
 'eps^p exp(-d eps^2)': (lambda p,e: e**p[0]*np.exp(-p[1]*e*e), 2),
}
Gt={
 'T^q': (lambda p,t: t**p[0], 1),
 'T^q cos(rT)': (lambda p,t: t**p[0]*np.cos(p[1]*t), 2),
 'T^q sin(rT)': (lambda p,t: t**p[0]*np.sin(p[1]*t), 2),
 'exp(rT)': (lambda p,t: np.exp(p[0]*t), 1),
 'T^q exp(rT)': (lambda p,t: t**p[0]*np.exp(p[1]*t), 2),
}
out=[]
np.random.seed(2)
for fn,(f,nf) in Ft.items():
  for gn,(g,ng) in Gt.items():
    npar=nf+ng
    best=None
    for k in range(12):
        p0=np.random.randn(npar+3)
        def fun(p):
            m=p[0]*np.sqrt(T)+p[1]*eps*np.exp(-p[2]*eps)/T+p[3]*f(p[4:4+nf],eps)*g(p[4+nf:],T)
            return m-s
        try:
            r_=least_squares(fun,p0,max_nfev=300)
        except Exception: continue
        if not np.all(np.isfinite(r_.fun)): continue
        if best is None or r_.cost<best.cost: best=r_
    if best is not None:
        out.append((np.sum(best.fun**2)/np.sum((s-s.mean())**2), fn, gn, best.x.round(4)))
out.sort(key=lambda x:x[0])
for o_ in out[:8]: print(o_)

